#include <iostream>
#include <vector>

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x = 0, ListNode* next = nullptr) : val(x), next(next) {}
};

// Reads a count and that many values, and links them into nodes.
ListNode* readList() {
    int n;
    std::cin >> n;
    std::vector<int> values(n);
    for (int i = 0; i < n; i++) {
        std::cin >> values[i];
    }
    ListNode* head = nullptr;
    for (int i = n - 1; i >= 0; i--) {
        head = new ListNode(values[i], head);
    }
    return head;
}

void printList(ListNode* head) {
    if (head == nullptr) {
        std::cout << "empty\n";
        return;
    }
    for (ListNode* node = head; node != nullptr; node = node->next) {
        std::cout << node->val << (node->next != nullptr ? " " : "\n");
    }
}

ListNode* reverseList(ListNode* head) {
    // TODO: reverse the list and return its new head
    return nullptr;
}

int main() {
    printList(reverseList(readList()));
    return 0;
}

